insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('beim-fechtn-entscheided-bei-gleichschdaund-im-finale-des-rittagfecht-iwan-easchdn-und-zweitn-plotz', 'Beim Fechtn entscheided bei Gleichschdaund im Finale des Rittagfecht iwan easchdn und zweitn Plotz!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Beim Fechten entscheidet bei Gleichstand im Finale das Rittergefecht über den ersten und zweiten Platz!', '[{"kategorie": "wörtlich, Fechtsport", "text": "\"Beim Fechten entscheidet bei Gleichstand im Finalkampf das Rittergefecht über Platz eins und zwei!\"  2. \"Steht es beim Fechten im Finale unentschieden, fällt die letzte Entscheidung im ''Rittergefecht''!\"  3. \"Bei Punktegleichheit im Fechtfinale wird der Sieger durch das sogenannte ''Rittergefecht'' ermittelt!\""}]'::jsonb, ''),
  ('des-projekt-is-ins-rittagfecht-gaungan-wia-nua-no-zwaa-voaschlaeg-iiwrich-woan', 'Des Projekt is ins Rittagfecht gaungan, wia nua no zwaa Voaschläg iiwrich woan!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Das Projekt ist ins Rittergefecht gegangen, als nur noch zwei Vorschläge übrig waren!', '[{"kategorie": "wörtlich", "text": "\"Das Projekt ging ins Rittergefecht, als nur noch zwei Konzepte übrig waren!\"  2. \"Am Schluss standen nur noch zwei Konzepte – und das Projekt ging in die finale Entscheidung!\"  3. \"Am Ende kam es zu einem Showdown zwischen den beiden letzten Projektvorschlägen, die da noch übrig waren!\""}]'::jsonb, ''),
  ('da-rock-passd-ia-guad-owa-de-foab-is-ned-meins', 'Da Rock passd ia guad - owa de Foab is ned meins!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der Rock passt ihr gut, aber die Farbe ist nicht meins!', '[{"kategorie": "wörtlich", "text": "\"Der Rock steht ihr gut, aber die Farbe gefällt mir nicht!\"  2. \"Ihr Rock sitzt perfekt – nur die Farbe ist halt nicht mein Ding!\"  3. \"Der Faltenrock passt ihr wie angegossen - aber farblich ist er leider daneben!\""}]'::jsonb, ''),
  ('a-beaumta-hod-sein-rock-in-da-vahaundlung-friara-nii-offn-troong-diafn-da-rock-hod-imma-zua-sei-miassn', 'A Beaumta hod sein Rock in da Vahaundlung friara nii offn troong diafn - da Rock hod imma zua sei miassn!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Ein Beamter hat seinen Rock in der Verhandlung früher nie offen tragen dürfen - der Rock hat immer zu sein müssen!', '[{"kategorie": "wörtlich", "text": "\"Der Beamte durfte seinen Rock während der Verhandlung früher nie offen tragen - der Rock musste stets geschlossen sein!\"  2. \"Bei Verhandlungen war offene Oberbekleidung früher tabu - die Jacke des Beamten musste stets geschlossen bleiben!\"  3. \"Früher durfte der Beamte bei der Verhandlung nicht mal dran denken, die Jacke offen zu lassen - die musste immer bis ganz oben zugeknöpft sein!\""}]'::jsonb, ''),
  ('des-is-a-pflaunz', 'Des is a Pflaunz!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Das ist ein Pflanz!', '[{"kategorie": "wörtlich", "text": "\"Das ist reine Frotzelei!\"  2. Das ist ein [[Häkel]]!  3. Das ist nichts als billige Veräppelung!  4. Das ist reine Verarsche!"}]'::jsonb, ''),
  ('des-is-a-haekl', 'Des is a Häkl!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Das ist ein Häkel!', '[{"kategorie": "wörtlich", "text": "\"Das ist nichts als Frotzelei!\"  2. Das ist ein [[Pflanz]]!  3. Das ist nichts als billige Veräppelung!  4. Das ist reine Verarsche!"}]'::jsonb, ''),
  ('des-is-a-reine-pflaunzarei', 'Des is a reine Pflaunzarei!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Das ist eine reine Pflanzerei', '[{"kategorie": "wörtlich", "text": "\"Das ist reine Frotzelei!\"  2. Das ist eine absolute Farce!  3. Das ist ein [[Häkel]]!  4. Das ist nichts als billige Veräppelung!  5. Das ist reine Verarsche!"}]'::jsonb, ''),
  ('wueuesd-mi-pflanzn', 'Wüüsd mi pflanzn?', '', '', '', 'Wiener Sprüche, die sitzen!', 'Willst du mich pflanzen?', '[{"kategorie": "wörtlich", "text": "\"Willst du mich verschaukeln?\"  2. \"Willst du mich auf den Arm nehmen?\"  3. \"Willst du mich frotzeln?\"  4. Willst du mich verarschen?  5. [[Wüüsd mi häkaln?]]"}]'::jsonb, 'Wüüsd mi häkaln?'),
  ('wueuesd-mi-haekaln', 'Wüüsd mi häkaln?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Willst du mich häkerln?', '[{"kategorie": "wörtlich", "text": "\"Willst du mich verschaukeln?\"  2. \"Willst du mich auf den Arm nehmen?\"  3. \"Willst du mich frotzeln?\"  4. Willst du mich verarschen?  5. [[Wüüsd mi pflanzn?]]"}]'::jsonb, 'Wüüsd mi pflanzn?'),
  ('pflanzn-s-wem-aundan', 'Pflanzn''S wem aundan!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Pflanzen Sie jemand anderen!', '[{"kategorie": "wörtlich", "text": "\"Verhöhnen Sie jemand anderen!\"  2. Frotzeln Sie jemand anderen, nicht mich!  3. Verschaukeln Sie jemand anderen, ich bin raus!  4. [[Häkerln]] Sie jemand anderen!"}]'::jsonb, ''),
  ('haekaln-s-wem-aundan', 'Häkaln''S wem aundan!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Häkerln Sie jemand anderen!', '[{"kategorie": "wörtlich", "text": "\"Verhöhnen Sie jemand anderen!\"  2. Frotzeln Sie jemand anderen, nicht mich!  3. Verschaukeln Sie jemand anderen, ich bin raus!  4. [[Pflanzen]] Sie jemand anderen!"}]'::jsonb, ''),
  ('an-pflaunz-reissen', 'an Pflaunz reißen', '', '', '', 'Wiener Sprüche, die sitzen!', 'einen Pflanz reißen', '[{"kategorie": "wörtlich", "text": "\"Possen reißen\""}, {"kategorie": "", "text": "Schmäh führen (auf jemandes Kosten)"}, {"kategorie": "", "text": "\"eine Verarsche abziehen\""}]'::jsonb, ''),
  ('ea-kaunns-ned-lossn-ea-muass-imma-iagendaan-pflaunz-reissn', 'Ea kaunns ned lossn - ea muass imma iagendaan Pflaunz reissn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Er kann''s nicht lassen - er muss immer irgendeinen Pflanz reißen!', '[{"kategorie": "wörtlich", "text": "\"Er kann''s nicht lassen - er muss immer irgendeine Verarsche abziehen!\"  2. Der Typ kann''s nicht lassen - er muss immer auf jemandes Kosten Schmäh führen!  3. Er kann einfach nicht ernst bleiben – immer ein Kommentar, immer ein Spruch!"}]'::jsonb, 'an Pflaunz reißen'),
  ('an-pflaunz-treibm', 'an Pflaunz treibm', '', '', '', 'Wiener Sprüche, die sitzen!', 'einen Pflanz treiben', '[{"kategorie": "wörtlich", "text": "\"Frotzelei betreiben\""}, {"kategorie": "", "text": "Schmäh führen (auf jemandes Kosten)"}, {"kategorie": "", "text": "\"eine Verarsche abziehen\""}]'::jsonb, 'Ea kaunns ned lossn - ea muass imma iagendaan Pflaunz treibm!'),
  ('ea-kaunns-ned-lossn-ea-muass-imma-iagendaan-pflaunz-treibm', 'Ea kaunns ned lossn - ea muass imma iagendaan Pflaunz treibm!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Er kann''s nicht lassen - er muss immer irgendeinen Pflanz treiben!', '[{"kategorie": "wörtlich", "text": "\"Er kann''s nicht lassen - er muss immer irgendeinen Blödsinn treiben!\"  2. Der Typ kann''s nicht lassen - er muss immer auf jemandes Kosten Schmäh führen!  3. Er kann einfach nicht ernst bleiben – immer ein Kommentar, immer ein Spruch!"}]'::jsonb, 'an Pflaunz treibm'),
  ('loss-di-von-dem-pflaunzreissa-ned-aeagan-dea-reed-imma-so-deppad-dahea', 'Loss di von dem Pflaunzreissa ned äagan - dea reed imma so deppad dahea!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Lass dich von dem Pflanzreißer nicht ärgern - der redet immer so deppert daher!', '[{"kategorie": "wörtlich", "text": "\"Reg dich über den Sprücheklopfer nicht auf - der redet ständig nur dummes Zeug!\"  2. Lass dir von diesem Großmaul nicht die Laune verderben – der hat immer irgendeinen Schmäh auf Lager!  3. Ignorier den Kasperl einfach – der spielt sich ständig so deppert auf!"}]'::jsonb, ''),
  ('da-michi-is-a-echta-pflaunzritta-groosse-goschn-nix-dahinta', 'Da Michi is a echta Pflaunzritta - groosse Goschn, nix dahinta!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der Michi ist ein echter Pflanzritter - große Goschen, nix dahinter!', '[{"kategorie": "wörtlich", "text": "\"Der Michi ist ein klassischer Maulheld – viel Gerede, aber nichts dahinter!\"  2. Der Michi ist ein typischer Aufschneider – reißt ständig den Mund auf, aber dahinter is nur heiße Luft  3. Der Michi ist ein Blender, wie er im Buche steht – viel Show, wenig Inhalt!"}]'::jsonb, ''),
  ('botanisch-is-da-pfeascha-a-schdaafrucht-mit-rosa-blia', 'Botanisch is da Pfeascha a Schdaafrucht mit rosa Blia!', '', '', '', 'Botanik und Pflanzen auf Wienerisch', 'Botanisch ist der Pferscher eine Steinfruckt mit rosa Blüten!', '[{"kategorie": "wörtlich", "text": "\"Aus botanischer Sicht handelt es sich beim Pfirsich um eine Steinfrucht mit rosafarbenen Blüten!\"  2. \"Der Pfirsich wird botanisch den Steinfrüchten zugeordnet und besitzt rosa Blüten!\"  3. \"Kennzeichnend für den Pfirsich sind die Steinfrucht und die rosa Blüten!\""}]'::jsonb, ''),
  ('a-gsichd-wiara-nockada-pfeascha', 'a Gsichd wiara nockada Pfeascha', '', '', '', 'Echte Wiener Schmähperlen', 'ein Gesicht wie ein nackter Pferscher', '[{"kategorie": "wörtlich", "text": "\"ein Gesicht wie ein nackter Pfirsich\""}, {"kategorie": "", "text": "\"ein Gesicht so glatt wie ein geschälter Pfirsich\""}, {"kategorie": "scherzhaft für", "text": "\"ein bartloses, pfirsichglattes Gesicht\""}]'::jsonb, 'Bei mia muass a Mau a Gsichd wiara nockada Pfeascha haum - I brauch ka Droodbiaschdl auf meina Haut!'),
  ('bei-mia-muass-a-mau-a-gsichd-wiara-nockada-pfeascha-haum-i-brauch-ka-droodbiaschdl-auf-meina-haut', 'Bei mia muass a Mau a Gsichd wiara nockada Pfeascha haum - I brauch ka Droodbiaschdl auf meina Haut!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Bei mir muss ein Mann ein Gesicht wie ein nackerter Pferscher haben - ich brauch kein Drahtbürstl auf meiner Haut!', '[{"kategorie": "wörtlich", "text": "\"Bei mir muss ein Mann ein Gesicht wie ein nackter Pfirsich haben - ich brauch'' keine Drahtbürste auf meiner Haut!\"  2. \"Bei mir muss ein Mann ein Gesicht so glatt wie ein geschälter Pfirsich haben - ich brauch'' keine kratzigen Bartbürsten auf meiner Haut!\"  3. \"Bei mir muss ein Mann glatt rasiert sein – ich brauch'' kein Schmirgelpapier im Gesicht!\""}]'::jsonb, 'a Gsichd wiara nockada Pfeascha'),
  ('a-so-an-pleampae-hauma-no-nii-in-da-fiama-ghobd', 'A so an Pleampä hauma no nii in da Fiama ghobd!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Einen solchen Plermpel haben wir noch nie in der Firma gehabt!', '[{"kategorie": "wörtlich", "text": "\"So einen Armleuchter hatten wir noch nie in der Firma!\"  2. Einen solchen Stümper hatten wir noch nie in der Firma!  3. So ein [[Dillo]] ist uns im Betrieb noch nie untergekommen!"}]'::jsonb, ''),
  ('de-koeoenarin-soit-amoi-leana-wia-ma-a-bia-seawiad-oone-z-plempan', 'De Köönarin soit amoi leana, wia ma a Bia seawiad, oone z''plempan!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Die Kellnerin sollte einmal lernen, wie man ein Bier serviert, ohne zu plempern!', '[{"kategorie": "wörtlich", "text": "\"Die Kellnerin sollte einmal lernen, wie man ein Bier serviert, ohne was zu vergießen!\"  2. \"Die Kellnerin sollte endlich lernen, ein Bier einzuschenken, ohne was zu verschütten!\""}]'::jsonb, ''),
  ('hea-auf-z-plempan-und-leeg-endlich-los', 'Hea auf z''plempan und leeg endlich los!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Hör auf zu plempern und leg endlich los!', '[{"kategorie": "wörtlich", "text": "\"Hör auf rumzutrödeln und fang endlich an!\"  2. \"Hör auf, Zeit zu vergeuden, und leg endlich los!\"  3. \"Plempern kannst du später, jetzt fang endlich an!\""}]'::jsonb, ''),
  ('ea-is-schdundnlaung-allaanich-dogsessn-und-hod-a-bia-nochn-aundan-plempad', 'Ea is schdundnlaung allaanich dogsessn und hod a Bia nochn aundan plempad!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Er ist stundenlang alleine dagesessen und hat ein Bier nach dem anderen geplempert!', '[{"kategorie": "wörtlich", "text": "\"Er saß stundenlang alleine da und kippte ein Bier nach dem anderen!\"  2. \"Er ist stundenlang alleine rumgehockt und hat sich ein Bier nach dem anderen reingeschüttet!\"  3. \"Der Typ saß ewig rum, ist allein am Tisch versackt und hat ein Bier ums nächste weggekippt!\""}]'::jsonb, ''),
  ('pass-auf-sunst-vaplempasd-noo-de-gaunze-mueuech', 'Pass auf, sunst vaplempasd noo de gaunze Müüch!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Pass auf, sonst verplemperst du noch die ganze Milch!', '[{"kategorie": "wörtlich", "text": "\"Gib Acht, sonst verschüttest du noch die ganze Milch!\"  2. \"Nicht so wild, sonst geht die ganze Milch noch daneben!\"  3. \"Halt still, sonst gießt du noch die ganze Milch aus!\""}]'::jsonb, ''),
  ('vaplempa-ned-so-vueue-zeit-und-goeoed-mit-so-an-schaas', 'Vaplempa ned so vüü Zeit und Gööd mit so an Schaas!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Verplemper'' nicht so viel Zeit und Geld mit so einem Schas!', '[{"kategorie": "wörtlich", "text": "\"Vergeude nicht sinnlos Zeit und Geld mit so ''nem Dreck!\"  2. \"Verheiz nicht dein Geld und deine Zeit für so einen Scheiß!\"  3. \"Verballer nicht deine Zeit und dein Geld für so einen Blödsinn!\""}]'::jsonb, ''),
  ('wos-soi-i-mit-dem-boofae', 'Wos soi I mit dem Boofä?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Was soll ich mit dem Pofel?', '[{"kategorie": "wörtlich", "text": "\"Was soll ich mit diesem Ramsch?\"  2. Was soll ich mit diesem Plunder?  3. Was soll ich mit diesem [[Klumpert]]?"}]'::jsonb, ''),
  ('wos-redst-do-fiaran-boofae-zsaumm', 'Wos redst do fiaran Boofä zsaumm?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Was redest du da für einen Pofel zusammen?', '[{"kategorie": "wörtlich", "text": "\"Was redest du da für sinnloses Zeug?\"  2. Was erzählst du da für einen Unsinn?  3. Was für einen Stuss gibst du da von dir?"}]'::jsonb, ''),
  ('de-heitige-mood-is-nix-ois-a-boofae', 'De heitige Mood is nix ois a Boofä!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die heutige Mode ist nichts als ein Pofel!', '[{"kategorie": "wörtlich", "text": "\"Die heutige Mode ist doch bloß Ramsch!\"  2. Die heutige Mode ist nichts weiter als billiger Plunder!  3. Die Mode von heute gleicht einem Ramschbasar!"}]'::jsonb, ''),
  ('a-boofae-rindsviicha', 'A Boofä Rindsviicha!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Ein Pofel Rindsviecher!', '[{"kategorie": "wörtlich", "text": "\"Ein Haufen Hornochsen!\"  2. Eine Ansammlung von Idioten!  3. Eine Horde von Trotteln!"}]'::jsonb, ''),
  ('da-gmaane-wiina-boofae', 'da gmaane Wiina Boofä', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'der gemeine Wiener Pofel', '[{"kategorie": "wörtlich", "text": "\"der gemeine Wiener Pöbel\""}, {"kategorie": "", "text": "das gemeine Wienervolk"}, {"kategorie": "", "text": "das Wiener Fußvolk"}]'::jsonb, 'Zwischn Hoof und Vuaschdodt hod ma friara schoaf untaschiedn, wos zum Oodl und wos zum gmaanan Wiina Boofä ghead!'),
  ('zwischn-hoof-und-vuaschdodt-hod-ma-friara-schoaf-untaschiedn-wos-zum-oodl-und-wos-zum-gmaanan-wiina-boofae-ghead', 'Zwischn Hoof und Vuaschdodt hod ma friara schoaf untaschiedn, wos zum Oodl und wos zum gmaanan Wiina Boofä ghead!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Zwischen Hof und Vorstadt hat man früher scharf unterschieden, was zum Adel und was zum gemeinen Wiener Pofel gehört!', '[{"kategorie": "wörtlich", "text": "\"Zwischen Hof und Vorstadt unterschied man früher streng, was dem Adel und was dem gemeinen Wienervolk zukam!\"  2. \"Zwischen Hof und Vorstadt verlief einst eine scharfe Grenze zwischen Adel und dem gemeinen Wiener Pöbel!\"  3. \"Was dem Adel zustand und was dem niederen Volk zufiel, war früher klar und streng geregelt!\""}]'::jsonb, ''),
  ('roode-ruabm', 'Roode Ruabm', 'die', '', '', 'Botanik und Pflanzen auf Wienerisch', 'Rote Rübe', '[{"kategorie": "wörtlich", "text": "\"Rote Rübe\" (vom mittelhochdeutschen \"rūebe\"=\"Rübe\")"}, {"kategorie": "bot.", "text": "\"Rote Rübe\" (Kulturform der gemeinen Rübe), (botanische Bezeichnung): \"Beta vulgaris\", [[Rauner]], (Deutschland): \"Rote Beete\""}]'::jsonb, 'A Roode Ruabm is kochd vüü müüda ois roo!'),
  ('a-roode-ruabm-is-kochd-vueue-mueueda-ois-roo', 'A Roode Ruabm is kochd vüü müüda ois roo!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Die Rote Rübe ist gekocht viel milder als roh!', '[{"kategorie": "wörtlich", "text": "\"Die Rote Beete ist gekocht viel milder als roh!\"  2. \"Gekocht schmeckt die Rote Rübe deutlich milder als roh!\"  3. \"Durch das Kochen verliert die Rote Rübe an Schärfe und schmeckt deshalb viel milder als roh!\""}]'::jsonb, 'Roode Ruabm'),
  ('schau-da-den-au-im-schbeckichn-ruadaleiwal-und-min-bia-in-da-haund-gaunz-groosses-kino', 'Schau da den au: im schbeckichn Ruadaleiwal und min Bia in da Haund - gaunz groosses Kino!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Schau ihn dir den an: im speckigen Ruderleibchen und mit ''nem Bier in der Hand – ganz großes Kino!', '[{"kategorie": "wörtlich", "text": "\"Schau dir den an – fettiges Ruderleibchen, Bier in der Pranke, echtes Spitzenprogramm!\"  2. \"Sieh dir den Vogel an: speckiges Leibchen, Biergriffel, Weltklasse-Auftritt!\"  3. \"Schau dir den an - speckiges Unterleiberl, Bier in der Hand – da weißt gleich, was los ist!\""}]'::jsonb, ''),
  ('an-russn-eakennsd-sofuat-ned-aun-da-kleidung-sondan-aun-seina-hoitung', 'An Russn eakennsd sofuat - ned aun da Kleidung, sondan aun seina Hoitung!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Einen Russen erkennst du sofort - nicht an seiner Kleidung, sondern an seiner Haltung!', '[{"kategorie": "wörtlich", "text": "\"Man erkennt einen Russen weniger an der Kleidung als an seiner Haltung!\"  2. \"Nicht die Kleidung verrät den Russen, sondern seine Haltung!\"  3. \"Man erkennt den Russen nicht an seinem Rocke, sondern an der Art, wie er dasteht und sich gibt!\""}]'::jsonb, ''),
  ('a-russ-wiad-klassisch-mit-roode-zwiifaen-loabeea-und-pfeefakeandln-seawiad', 'A Russ wiad klassisch mit roode Zwiifän, Loabeea und Pfeefakeandln seawiad!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Der Russe wird klassisch mit roten Zwiebeln, Lorbeer und Pfefferkörnern serviert!', '[{"kategorie": "wörtlich", "text": "\"Traditionell richtet man den Russen mit roten Zwiebeln, Lorbeer und Pfefferkörnern an!\"  2. \"Zum Russen - dem ausgenommenen, marinierten, kleinen Hering mit Schwanz, aber ohne Kopf - gehören klassisch rote Zwiebeln, Lorbeer und Pfefferkörner!\"  3. \"Serviert wird der Russe in klassischer Begleitung von roten Zwiebeln, Lorbeer und Pfefferkörnern!\""}]'::jsonb, ''),
  ('rotz1', 'Rotz1', 'der', '', '', 'Grundwortschatz Wienerisch', 'Rotz', '[{"kategorie": "wörtlich", "text": "\"Rotz\" (vom mittelhochdeutschen \"roz\"=\"Nasenausfluss\")"}, {"kategorie": "allg.", "text": "\"Nasenschleim\", Nasensekret, [[Raummä]], [[Noosnraummä]], [[Noosnwuuzl]], [[Rawuuzl]], [[Noosnmaumau]], (Deutschland): \"Popel\""}, {"kategorie": "fig., Gaunersprache", "text": "Geld, Schotter, Kohle, [[Marie]] ([[Eam is da Rotz ausgaungan!]])"}, {"kategorie": "fig.", "text": "Unannehmlichkeit, Ungemach, Dreck, Ärger, Schlamassel"}]'::jsonb, 'Ollas volla Rotz - kaa Wunda bei dem Schnupfn!'),
