  ('rotz2', 'Rotz2', 'der', '', '', 'Grundwortschatz Wienerisch', 'Ratz', '[{"kategorie": "wörtlich", "text": "\"Ratte\" (vom mittelhochdeutschen \"ratte\"=\"Ratte\")"}, {"kategorie": "zool.", "text": "Hausratte, Nager, Nagetier"}, {"kategorie": "fig., in Bezug auf Personen", "text": "Schuft, Halunke, Verräter, [[linker]] Hund, [[Haut]], [[Gfraasdsackl]]"}]'::jsonb, 'Pass auf den do auf - des is a Rotz easchda Klass!'),
